List<MapEntry<String, double>> getTopCoins({required Map<String, List<double>> averages, required bool isProfit}) {
  final sortedEntries = averages.entries.map((entry) => MapEntry(entry.key, entry.value.reduce((a, b) => a + b) / entry.value.length)).toList();
  sortedEntries.sort((a, b) {
    if (isProfit) {
      return b.value.compareTo(a.value);
    } else {
      return a.value.compareTo(b.value);
    }
  });

  return sortedEntries.take(6).skip(3 - (isProfit ? 0 : 3)).toList();
}

