function switchAdjectiveOrder(sentence) {
  const wordList = sentence.split(' '); // Split sentence into words
  const regex = /((\b[Jj][a-z]{2,}\s)?\w+(?:\s|$))+ (\b[A-Z][a-z]{1,}[a-z]+(?:\s|$))+/g; // RegExp to match patterns like "green beautiful" or "beautiful green"
  let match;
  const adjectives = [];

  while ((match = regex.exec(sentence)) !== null) {
    adjectives.push(match[0]); // Save matched adjectives to array
    sentence = sentence.replace(match[0], '$2 $1'); // Swap the order in the original sentence
  }

  return sentence.trim() + ' ' + adjectives.join(' ') + '.'; // Add swapped sentence and original adjectives back together
}

console.log(switchAdjectiveOrder("Beautiful green trees are in the park")); // Output: "Green beautiful trees are in the park."
