```javascript
function sortJsonObjectByKeys(jsonObj) {
  // Convert JSON object to an array of key-value pairs
  const entries = Object.entries(jsonObj);

  // Sort the array of key-value pairs based on keys
  const sortedEntries = entries.sort((a, b) => {
    return String.compare(a[0], b[0]);
  });

  // Create a new JSON object from the sorted array of key-value pairs
  const sortedJsonObj = Object.fromEntries(sortedEntries);

  return sortedJsonObj;
}

