func correctHomophones(_ text: String) -> String {
    var words: [String] = text.components(separatedBy: CharacterSet.whitespacesAndNewlines)

    for (homophonePair, correction) in homophones {
        for i in 0..<words.count {
            if words[i].lowercased().hasSuffix(" \(homophonePair.1)") {
                words[i] = String(words[i].prefix(words[i].index(words[i].endIndex, offsetBy: -1)!)).appended(correction)
            }
        }
    }

    return words.joined(separator: " ")
}

