Next, we'll define a function to replace homophones in the given text:

```swift
func replaceHomophones(_ text: String) -> String {
    var words: [String] = text.components(separatedBy: " ")

    for (index, word) in words.enumerated() {
        if let replacement = wordReplacements[word.lowercased()] {
            words[index] = replacement
        }
    }

    return String(words.joined(separator: " "))
}
```

