```swift
struct ProductReview {
    let text: String
    let rating: Int
}

func fetchProductReviews(completion: @escaping ([ProductReview]) -> Void) {
    guard let url = URL(string: "https://api.example.com/product-reviews") else { return }

    URLSession.shared.dataTask(with: url) { (data, response, error) in
        if let data = data, let json = try? JSONSerialization.jsonObject(from: data, options: []) as? [[String: Any]] {
            var reviews: [ProductReview] = []
            for reviewData in json {
                if let text = reviewData["text"] as? String, let rating = reviewData["rating"] as? Int {
                    reviews.append(ProductReview(text: text, rating: rating))
                }
            }
            completion(reviews)
        }
    }.resume()
}
```

