function determineProtocol(inputData) {
  let ipVersion;
  if (/^([0-9]{4}::)([0-9]{4}){5}([0-9]{1,4}|:)/g.test(inputData.sourceIP)) { // check for IPv6 format
    ipVersion = 6;
  } else { // assume IPv4 or invalid IP address
    ipVersion = 4;
  }

  const protocolMap = {
    4: {
      "IP": true,
      "HTTP": inputData.port === 80,
      "UDP": false
    },
    6: {
      "IP": true,
      "HTTP": inputData.port && ["HTTP", "HTTPS"].includes(protocolFromPort(inputData.port)),
      "UDP": inputData.payload ? inputData.payload.length > 0 : false // assume non-empty payload indicates UDP
    }
  };

  const relevantProtocols = Object.keys(protocolMap[ipVersion])
    .filter(p => protocolMap[ipVersion][p])
    .map(p => p.charAt(0).toUpperCase() + p.slice(1)); // capitalize first letter

  return relevantProtocols.length > 0 ? relevantProtocols[0] : "Unknown";

  function protocolFromPort(port) {
    switch (port) {
      case 80:
        return "HTTP";
      case 8080:
        return "HTTP-Proxy"; // assuming this as an example of another HTTP-like protocol
      case 13:
        return "Telnet";
      case 53:
        return "DNS";
      case 67:
        return "Bootstrap Protocol (BOOTP)";
      default:
        return "";
    }
  }
}
