  const dataRange = sheet.getDataRange();
  const data = dataRange.getValues();

  // Process each row in the data range.
  const results = [];
  for (let i = 0; i < data.length; i++) {
    const placeName = data[i][0];
    if (!placeName) continue; // Skip empty cells

    try {
      const location = Maps.newGeocoder().geocode(placeName)[0].geometry.location;
      results.push([placeName, location.lat(), location.lng()]);
    } catch (error) {
      Logger.log(`Error geocoding ${placeName}: ${error}`);
    }
  }

