```php
function smart_sort_array($set, $order = 'ASC') {
    $n = count($set);
    for ($i = 0; $i < $n - 1; $i++) {
        for ($j = 0; $j < $n - $i - 1; $j++) {
            if (($order == 'ASC' && $set[$j]['age'] > $set[$j+1]['age']) || ($order == 'DESC' && $set[$j]['age'] < $set[$j+1]['age'])) {
                // Swap the elements
                $temp = $set[$j];
                $set[$j] = $set[$j+1];
                $set[$j+1] = $temp;
            }
        }
    }
    return $set;
}
```

