 To create a decorator for a Nest.js middleware function that checks the `NODE_ENV` environment variable and returns `next()` if it equals "true" and `false` otherwise, follow these steps:

First, let's define the decorator. We'll name it `CheckNodeEnv`. This decorator will accept an optional parameter `allowedEnvValues`, which is an array of allowed values for the `NODE_ENV` variable. If this parameter is not provided, the default value will be ["true"].

```typescript
import { createParamDecorator, ExecutionContext } from '@nestjs/common';
import * as process from 'process';

export const CheckNodeEnv = (allowedEnvValues: string[] = ['true']): PropertyDecorator => {
  return (target: Object, propertyKey: string, descriptor: PropertyDescriptor) => {
    const originalMethod = descriptor.value;

    descriptor.value = async function(req: Request, res: Response, next: Function) {
      const nodeEnv = process.env.NODE_ENV;

      if (nodeEnv === null || (allowedEnvValues.length && allowedEnvValues.includes(nodeEnv))) {
        await originalMethod.apply(this, arguments);
        next();
      } else {
        res.status(403).send(false);
      }
    };

    return descriptor;
  };
};
```

Now, you can use this decorator with your middleware functions:

```typescript
import { Controller, Get, UseGuards, Req, Res } from '@nestjs/common';
import { Request, Response } from 'express';
import { CheckNodeEnv } from './check-node-env.decorator';

@Controller('api')
export class AppController {
  @UseGuards()
  @Get('protected-route')
  @CheckNodeEnv() // or @CheckNodeEnv(['production']) for specific env
  async protectedRoute(@Req() req: Request, @Res() res: Response) {
    // Your code here
  }
}
```

