def number_to_words(num):
    if num == 0:
        return "zero"

    def number_to_words_helper(num, n):
        if num >= n:
            word = singular[num // n]
            return f"{word} {number_to_words_helper(num % n, n)}"
        else:
            return ""

    thousands, num = divmod(abs(num), 1000)
    millions, thousands = divmod(thousands, 1000000)
    billions, millions = divmod(millions, 1000000000)

    words = []

    if billions > 0:
        words.append(plurals[int(billions)] + " billion")

    if millions > 0:
        words.append(number_to_words_helper(millions, 1000000))
        words.append("million")

    if thousands > 0:
        words.append(number_to_words_helper(thousands, 1000))
        words.append("thousand")

    if num != 0:
        words.append(singular[int(num // 1)] + " hundred " + number_to_words_helper(num % 100, 10))

    return ' '.join(words)[::-1] if num < 0 else ' '.join(words)

