import React, { useState } from "react";
import { useCombobox } from "react-downshift";
import axios from "axios";

interface Option {
  value: string;
  label: string;
}

const EmailInput: React.FC = () => {
  const [inputItems, setInputItems] = useState<Option[]>([]);
  const { isOpen, getMenuProps, getComboboxProps, highlightedIndex, getItemProps } = useCombobox({
    items: inputItems,
    onChange: (item) => setInputItems((prev) => [...prev, ...(item ? [item] : [])]),
    onInputValueChange: async ({ inputValue }) => {
      if (inputValue === "") {
        setInputItems([]);
        return;
      }
      try {
        const response = await axios.get("/api/searchEmails", { params: { prefix: inputValue } });
        setInputItems(response.data.map((email: any) => ({ value: email, label: email })));
      } catch (error) {
        console.error("Error fetching emails:", error);
      }
    },
  });

  return (
    <div>
      <input {...getComboboxProps()} placeholder="Enter email address" />
      <ul {...getMenuProps()}>
        {isOpen &&
          inputItems.map((option, index) => (
            <li key={option.value} {...getItemProps({ item: option, index })}>
              {option.label}
            </li>
          ))}
      </ul>
    </div>
  );
};

export default EmailInput;
```

