  return isSingleWordOrSyllable;
}
```

Now, we can create our HOC called `NoWidows` that accepts a component and adjusts its rendering when necessary:

```jsx
import React from 'react';

function NoWidows({ children }) {
  const textComponents = React.Children.toArray(children).filter(child => child && child.type === String);

  const paragraphComponents = textComponents.map((textComponent, index) => {
    const text = textComponent.props.children;
    const hasWidow = noWidows(text);

    if (!hasWidow) return textComponent;

    // Adjust the line height and add an extra line break to prevent widows
    return React.cloneElement(textComponent, { style: { lineHeight: '1.5', marginBottom: '1em' } });
  });

  return <>{paragraphComponents}</>;
}

export default NoWidows;
```

