Here's a simple React utility function using the `react-text` library for text measurement:

1. First, install the `react-text` package by running `npm install react-text` or `yarn add react-text`.

2. Create a new file called `removeWidows.js` and add the following code:

```javascript
import Text from 'react-text';

const removeWidows = (text, lineHeight, maxLines) => {
  const lines = text.split('\n');
  let currentLineIndex = 0;
  const result = [];

  while (result.length < maxLines && currentLineIndex < lines.length) {
    const lineText = lines[currentLineIndex];
    const measuredText = Text.measure(lineText).width;
    const nextLineText = lines[currentLineIndex + 1];

    if (!nextLineText || measuredText + Text.measure(nextLineText).width > maxWidth - lineSpacing) {
      // Break the current line if it exceeds the maximum width or there's no next line.
      result.push(<span key={`line_${currentLineIndex}`}>{lineText}</span>);
      currentLineIndex++;
    } else {
      // Merge the current and next lines into a single line and advance to the next line.
      result.push(<span key={`line_${currentLineIndex}`}>{lineText} {nextLineText}</span>);
      currentLineIndex += 1;
    }
  }

  return result;
};

const maxWidth = 800; // Set your desired maximum width.
const lineSpacing = 20; // Set your desired line height.

export default removeWidows;
```

